let aiConfig={cloud:false,services:[],mapping:{}};
try{const saved=JSON.parse(localStorage.getItem('gam264-ai-settings')||'null');if(saved&&Array.isArray(saved.services))aiConfig=saved}catch(e){}
let aiDraft=null;
const aiTasks=[['ocr','圖面文字辨識 OCR','圖面影像或 PDF'],['detect','敏感資訊候選區偵測','圖面影像或 PDF'],['translate','專業文字翻譯','選取文字；預留術語庫輔助']];
function aiAdmin(){return typeof members==='undefined'||members.find(m=>m.id==='member-1')?.role==='admin'}
function aiPersist(next){try{localStorage.setItem('gam264-ai-settings',JSON.stringify(next));aiConfig=next;return true}catch(e){notify('無法儲存設定，請確認瀏覽器儲存空間。');return false}}
function aiLocation(v){return ({local:'本機',intranet:'公司內網',cloud:'外部雲端'})[v]}
function aiStatus(s){return s.enabled?'已啟用（示範）':s.test==='success'?'測試成功（示範）':s.test==='failed'?'測試失敗（示範）':'未驗證／未啟用'}
function aiPage(){const admin=aiAdmin();return title('AI 服務設定','設定部署環境共用的服務與功能對應。')+`<div class="note">互動原型：測試結果為示範，不發出網路請求、不接受或保存真實 API 金鑰。正式權限與服務呼叫待後端串接。</div><div class="ai-settings"><section class="card"><div class="cardhead"><div><h2>連線與資料傳送政策</h2><p>適用範圍：此部署環境共用 · 僅最高管理權限可修改</p></div><span class="badge ${aiConfig.cloud?'orange':'green'}">${aiConfig.cloud?'允許雲端（示範）':'雲端已關閉'}</span></div><label class="checkrow ai-cloud-toggle"><input id="aiCloudToggle" type="checkbox" ${aiConfig.cloud?'checked':''} ${admin?'':'disabled'} onchange="aiCloud(this.checked)">允許使用外部雲端 AI</label><p>關閉時，雲端服務不可測試或啟用。服務失敗不會自動改送雲端；人工遮蔽、備註與核對仍可操作。</p><p>「本機」指執行系統後端的電腦；公司內網部署時通常是內部主機。</p></section><section class="card"><div class="cardhead"><div><h2>AI 服務連線</h2><p>先設定連線，再測試、儲存並啟用。</p></div><button class="primary" ${admin?'':'disabled'} onclick="aiEdit()">新增服務</button></div><div class="ai-service-grid">${aiConfig.services.map((s,i)=>`<article class="ai-service"><div class="cardhead"><h3>${esc(s.name)}</h3><span class="badge ${s.enabled?'green':s.test==='failed'?'red':'blue'}">${aiStatus(s)}</span></div><dl><dt>部署位置</dt><dd>${aiLocation(s.location)}</dd><dt>介接方式</dt><dd>${esc(s.type)}</dd><dt>服務位址</dt><dd>${esc(s.url)}</dd><dt>模型</dt><dd>${esc(s.model||'不適用')}</dd><dt>認證</dt><dd>${s.auth==='key'?'示範金鑰占位':'無認證'}</dd><dt>最近測試</dt><dd>${s.testAt?esc(new Date(s.testAt).toLocaleString('zh-TW')):'尚未測試'}</dd></dl>${s.error?`<p class="ai-error">${esc(s.error)}</p>`:''}<div class="actions"><button ${admin?'':'disabled'} onclick="aiEdit(${i})">編輯</button><button ${!admin||(!s.enabled&&(s.test!=='success'||(s.location==='cloud'&&!aiConfig.cloud)))?'disabled':''} onclick="aiToggle(${i})">${s.enabled?'停用':'啟用'}</button></div>${!s.enabled&&s.test!=='success'?'<small>完成示範測試後才能啟用。</small>':''}</article>`).join('')||'<div class="ai-empty"><h3>尚未設定 AI 服務</h3><p>新增本機、公司內網或雲端連線。未設定不影響人工圖面作業。</p></div>'}</div></section><section class="card"><h2>功能與服務對應</h2><p>連線成功不代表功能已串接；以下對應僅供流程展示。</p>${aiTasks.map(([key,label,data])=>`<div class="ai-mapping"><div><b>${label}</b><p>處理資料：${data}</p><span class="badge">尚未串接</span></div><label class="field">指定服務<select ${admin?'':'disabled'} onchange="aiMap('${key}',this.value)"><option value="">不使用 AI 服務</option>${aiConfig.services.map(s=>`<option value="${s.id}" ${aiConfig.mapping[key]===s.id?'selected':''} ${s.enabled?'':'disabled'}>${esc(s.name)} · ${aiLocation(s.location)}${s.enabled?'':' · 未啟用'}</option>`).join('')}</select></label></div>`).join('')}<p class="note">人工遮蔽、備註、核對及 PDF 成果產生不與 AI 金鑰綁定。AI 候選結果仍須人工確認。</p></section></div>`}
function aiCloud(enabled){if(!aiAdmin())return;const toggle=document.querySelector('#aiCloudToggle');if(toggle)toggle.checked=aiConfig.cloud;if(enabled){document.querySelector('#aiCloudConfirm')?.remove();const d=document.createElement('dialog');d.id='aiCloudConfirm';d.className='ai-dialog';d.setAttribute('aria-labelledby','aiCloudConfirmTitle');d.innerHTML=`<h2 id="aiCloudConfirmTitle">允許使用外部雲端 AI？</h2><p>正式串接後，指定功能的文字或圖面將傳送至您設定的雲端服務。</p><div class="note">目前為互動原型，開啟後只允許設定及示範測試，不會發出真實請求。</div><div class="actions ai-dialog-actions"><button type="button" autofocus onclick="document.querySelector('#aiCloudConfirm').close()">取消</button><button type="button" class="primary" onclick="aiConfirmCloud()">確認開啟</button></div>`;document.body.append(d);d.showModal();return}aiApplyCloud(false)}
function aiConfirmCloud(){if(!aiAdmin())return;if(aiApplyCloud(true))document.querySelector('#aiCloudConfirm')?.close()}
function aiApplyCloud(enabled){if(!aiAdmin())return false;const next=structuredClone(aiConfig);next.cloud=enabled;if(!enabled){next.services.forEach(s=>{if(s.location==='cloud')s.enabled=false});for(const k in next.mapping)if(next.services.find(s=>s.id===next.mapping[k])?.location==='cloud')next.mapping[k]=''}if(aiPersist(next)){render();notify(enabled?'已允許使用外部雲端 AI（示範）':'外部雲端 AI 已關閉');return true}return false}
function aiMap(key,value){if(!aiAdmin())return;const next=structuredClone(aiConfig);next.mapping[key]=value;if(aiPersist(next))notify('功能對應已儲存（尚未串接）')}
function aiToggle(i){if(!aiAdmin())return;const next=structuredClone(aiConfig),s=next.services[i];if(!s.enabled&&(s.test!=='success'||(s.location==='cloud'&&!next.cloud)))return;s.enabled=!s.enabled;if(!s.enabled)for(const k in next.mapping)if(next.mapping[k]===s.id)next.mapping[k]='';if(aiPersist(next)){render();notify(s.enabled?'服務已啟用（示範）':'服務已停用，已解除功能對應')}}
function aiEdit(i){if(!aiAdmin())return;aiDraft=i===undefined?{id:'ai-'+Date.now(),name:'',location:'local',type:'OpenAI 相容介面',url:'http://localhost:11434/v1',auth:'none',model:'',test:'',enabled:false}:structuredClone(aiConfig.services[i]);aiDraft.index=i;aiDialog()}
function aiDialog(){document.querySelector('#aiDialog')?.remove();const s=aiDraft,d=document.createElement('dialog');d.id='aiDialog';d.className='ai-dialog';d.setAttribute('aria-labelledby','aiDialogTitle');d.innerHTML=`<form onsubmit="aiSave(event)"><h2 id="aiDialogTitle">${s.index===undefined?'新增':'編輯'} AI 服務</h2><p>使用示範資料測試設定流程，不輸入真實金鑰。</p><div class="formgrid"><label class="field">服務名稱<input required maxlength="60" value="${esc(s.name)}" oninput="aiDraft.name=this.value"></label><label class="field">部署位置<select onchange="aiChange('location',this.value);aiDialog()">${['local','intranet','cloud'].map(v=>`<option value="${v}" ${s.location===v?'selected':''}>${aiLocation(v)}</option>`).join('')}</select></label><label class="field">服務類型／介接方式<select onchange="aiChange('type',this.value);aiDialog()">${['OpenAI 相容介面','自訂 OCR 服務','自訂偵測服務'].map(v=>`<option ${s.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">認證方式<select onchange="aiChange('auth',this.value);aiDialog()"><option value="none" ${s.auth==='none'?'selected':''}>無認證</option><option value="key" ${s.auth==='key'?'selected':''}>API Key</option></select></label><label class="field ai-wide">服務位址<input type="url" required value="${esc(s.url)}" placeholder="請輸入服務的基底位址" oninput="aiChange('url',this.value)"></label>${s.type==='OpenAI 相容介面'?`<label class="field ai-wide">模型<input required value="${esc(s.model)}" placeholder="輸入模型識別名稱" oninput="aiChange('model',this.value)"><small>原型先手動輸入；正式串接後可載入模型清單。</small></label>`:''}${s.auth==='key'?'<label class="field ai-wide">API Key<input type="password" disabled value="demo-placeholder" aria-label="示範金鑰占位，禁止輸入真實金鑰"><small>正式版本由後端安全保存；此處僅顯示占位。</small></label>':''}</div><div class="ai-test"><label class="field">示範測試情境<select id="aiScenario"><option value="success">連線成功</option><option value="auth">認證失敗</option><option value="timeout">連線逾時</option><option value="model">模型不存在</option></select></label><button type="button" ${s.location==='cloud'&&!aiConfig.cloud?'disabled':''} onclick="aiTest()">測試連線（示範）</button><p id="aiTestResult" role="status">${s.location==='cloud'&&!aiConfig.cloud?'雲端政策已關閉，無法測試。':s.test?aiStatus(s)+(s.error?'：'+esc(s.error):''):'尚未測試'}</p></div><div class="actions ai-dialog-actions"><button type="button" onclick="document.querySelector('#aiDialog').close();aiDraft=null">取消</button><button type="submit" class="primary">儲存設定</button></div></form>`;document.body.append(d);d.showModal();d.addEventListener('cancel',()=>{aiDraft=null})}
function aiChange(key,value){aiDraft[key]=value;aiDraft.test='';aiDraft.testAt=null;aiDraft.error='';aiDraft.enabled=false;if(key==='location'){aiDraft.url='';aiDraft.auth=value==='cloud'?'key':'none'}const hint=document.querySelector('#aiTestResult');if(hint)hint.textContent='連線設定已變更，請重新測試。'}
function aiValidate(){const s=aiDraft;try{const u=new URL(s.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)return '請使用不含帳密、查詢參數的 HTTP／HTTPS 服務位址。';if(s.location==='cloud'&&u.protocol!=='https:')return '雲端服務請使用 HTTPS。'}catch(e){return '請填寫有效服務位址。'}if(!s.name.trim())return '請填寫服務名稱。';if(s.type==='OpenAI 相容介面'&&!s.model.trim())return '請填寫模型名稱。';return ''}
function aiTest(){if(!aiAdmin()||!aiDraft)return;if(aiDraft.location==='cloud'&&!aiConfig.cloud)return;const error=aiValidate(),hint=document.querySelector('#aiTestResult');if(error){hint.textContent=error;return}const scenario=document.querySelector('#aiScenario').value;aiDraft.test=scenario==='success'?'success':'failed';aiDraft.enabled=false;aiDraft.testAt=new Date().toISOString();aiDraft.error=({auth:'認證失敗，請確認認證方式與金鑰。',timeout:'連線逾時，請確認服務已啟動及網路位址。',model:'模型不存在，請確認模型名稱。'})[scenario]||'';hint.textContent=scenario==='success'?'示範測試成功；未發出真實請求。':aiDraft.error+'（示範）'}
function aiSave(e){e.preventDefault();if(!aiAdmin())return;const error=aiValidate();if(error){document.querySelector('#aiTestResult').textContent=error;return}const next=structuredClone(aiConfig),s={...aiDraft};delete s.index;if(s.type!=='OpenAI 相容介面')s.model='';if(aiDraft.index===undefined)next.services.push(s);else next.services[aiDraft.index]=s;if(!s.enabled)for(const k in next.mapping)if(next.mapping[k]===s.id)next.mapping[k]='';if(aiPersist(next)){document.querySelector('#aiDialog').close();aiDraft=null;render();notify('服務設定已儲存')}}
